import React, { useState, useMemo } from 'react';
import PropertyCard from './PropertyCard';
import SkeletonCard from './SkeletonCard';

function PropertyList({ properties, handleDeleteProperty, handleEditProperty, onOpenCalculator, favorites = [], toggleFavorite, isFavoritesView = false, compareList = [], toggleCompare, onScheduleVisit, onViewDetails, onShowMap, onShow360, loading, isCompact }) {
    const perPage = isCompact ? 12 : 6;
    const [page, setPage] = useState(1);
    const [sortKey, setSortKey] = useState('price');
    const [sortDir, setSortDir] = useState('asc');

    const sorted = useMemo(() => {
        const copy = [...properties];
        copy.sort((a,b) => {
            const av = a[sortKey] ?? 0;
            const bv = b[sortKey] ?? 0;
            if (av < bv) return sortDir === 'asc' ? -1 : 1;
            if (av > bv) return sortDir === 'asc' ? 1 : -1;
            return 0;
        });
        return copy;
    }, [properties, sortKey, sortDir]);

    const total = sorted.length;
    const pages = Math.max(1, Math.ceil(total / perPage));
    const visible = sorted.slice((page-1)*perPage, page*perPage);

    const shareProperty = (prop) => {
        const text = `فرصة عقارية مميزة! 🏠\n*${prop.type} ${prop.status}*\n📍 الموقع: ${prop.location?.city} - ${prop.location?.neighborhood || ''}\n💰 السعر: ${prop.price?.toLocaleString()} جنيه\n📏 المساحة: ${prop.area} م²\n\nللتواصل: ${prop.ownerPhone}`;
        const url = `https://wa.me/?text=${encodeURIComponent(text)}`;
        window.open(url, '_blank');
    };

    const copyDetails = (prop) => {
        const text = `نوع العقار: ${prop.type}\nالحالة: ${prop.status}\nالموقع: ${prop.location?.city}\nالسعر: ${prop.price?.toLocaleString()} جنيه\nالتفاصيل: ${prop.description}\nرقم المالك: ${prop.ownerPhone}`;
        navigator.clipboard.writeText(text);
        alert('تم نسخ تفاصيل العقار للحافظة! 📋');
    };

    const handlePrint = (prop) => {
        const printWindow = window.open('', '_blank');
        printWindow.document.write(`
          <html dir="rtl">
            <head>
              <title>طباعة - ${prop.description}</title>
              <style>
                body { font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif; padding: 40px; color: #333; }
                .header { text-align: center; border-bottom: 3px solid #0d6efd; padding-bottom: 20px; margin-bottom: 30px; }
                .img-box { width: 100%; height: 400px; background-image: url('${prop.imageUrl}'); background-size: cover; background-position: center; border-radius: 15px; margin-bottom: 30px; }
                .details { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; font-size: 18px; }
                .price-tag { background: #198754; color: white; padding: 10px 20px; border-radius: 10px; font-size: 24px; font-weight: bold; display: inline-block; margin-top: 20px; }
                .footer { margin-top: 50px; text-align: center; font-size: 14px; color: #777; border-top: 1px solid #ddd; padding-top: 20px; }
              </style>
            </head>
            <body>
              <div class="header">
                <h1>${prop.type} ${prop.status} - ${prop.location?.city}</h1>
                <p>${prop.description}</p>
              </div>
              <div class="img-box"></div>
              <div class="details">
                <p><strong>📍 الموقع:</strong> ${prop.location?.city} - ${prop.location?.neighborhood}</p>
                <p><strong>📏 المساحة:</strong> ${prop.area} متر مربع</p>
                <p><strong>🛋️ الغرف:</strong> ${prop.rooms}</p>
                <p><strong>🛁 الحمامات:</strong> ${prop.bathrooms}</p>
                <p><strong>📞 للتواصل:</strong> ${prop.ownerPhone}</p>
                <p><strong>👤 المالك:</strong> ${prop.ownerName}</p>
              </div>
              <div style="text-align:center"><div class="price-tag">${prop.price?.toLocaleString()} جنيه مصري</div></div>
              <div class="footer">تم استخراج هذا المستند من منصة سمسار العقارية</div>
              <script>window.print();</script>
            </body>
          </html>
        `);
        printWindow.document.close();
    };

    return (
        <div>
            <h2 className="mb-4 text-white" style={{textShadow: '0 2px 4px rgba(0,0,0,0.5)'}}>{isFavoritesView ? '❤️ العقارات المفضلة' : '🏢 المخزون العقاري'}</h2>

            <div className="d-flex align-items-center mb-3">
                <div className="me-3">
                    <label className="form-label me-2 small">ترتيب:</label>
                    <select className="form-select form-select-sm d-inline-block" style={{width:160}} value={sortKey} onChange={e => setSortKey(e.target.value)}>
                        <option value="price">السعر</option>
                        <option value="area">المساحة</option>
                        <option value="rooms">الغرف</option>
                    </select>
                    <button className="btn btn-sm btn-outline-secondary ms-2" onClick={() => setSortDir(d => d === 'asc' ? 'desc' : 'asc')}>{sortDir === 'asc' ? '↑' : '↓'}</button>
                </div>

                <div className="ms-auto small text-muted">{total} عقار · صفحة {page} من {pages}</div>
            </div>

            <div className="row">
                {loading ? (
                    Array.from({ length: perPage }).map((_, i) => <SkeletonCard key={i} />)
                ) : visible.length > 0 ? (
                    visible.map((prop, index) => (
                        <div key={prop.id} className={`${isCompact ? 'col-6 col-md-4 col-lg-3' : 'col-md-6 col-lg-4'} mb-4 fade-in`} style={{ animationDelay: `${index * 0.05}s` }}>
                            <PropertyCard 
                                prop={prop}
                                isFav={favorites.includes(prop.id)}
                                isCompact={isCompact}
                                isComparing={compareList.includes(prop.id)}
                                {...{onViewDetails, onShow360, onShowMap, toggleFavorite, toggleCompare, onScheduleVisit, handlePrint, shareProperty, copyDetails, onOpenCalculator, handleEditProperty, handleDeleteProperty}}
                            />
                        </div>
                    ))
                ) : (
                    <div className="col-12 text-center py-5">
                        <div className="card p-5">
                            <h3>🏠</h3>
                            <h4 className="text-muted">لا توجد عقارات للعرض</h4>
                            <p className="text-muted">حاول تغيير فلاتر البحث أو قم بإضافة عقارات جديدة.</p>
                        </div>
                    </div>
                )}
            </div>

            <div className="d-flex justify-content-between align-items-center">
                <div>
                    <button className="btn btn-sm btn-outline-secondary me-2" disabled={page<=1} onClick={() => setPage(p=>Math.max(1,p-1))}>السابق</button>
                    <button className="btn btn-sm btn-outline-secondary" disabled={page>=pages} onClick={() => setPage(p=>Math.min(pages,p+1))}>التالي</button>
                </div>
                <div className="small text-muted">عرض {visible.length} من {total}</div>
            </div>
        </div>
    );
}

export default PropertyList;
